from pytest import mark
from focal_module import download_dependencies

@mark.parametrize("dependencies", [
    ["package1", "package2"],
    None,
    0,
    [],
    ["package3"],
    ["package1", None, "package3"],
    ["package1", 0, "package3"]
])
def test_download_dependencies(dependencies):
    if dependencies is None or dependencies == 0:
        with pytest.raises(TypeError):
            download_dependencies(dependencies)
    elif len(dependencies) == 0:
        assert download_dependencies(dependencies) == []
    elif len(dependencies) == 1:
        assert download_dependencies(dependencies) == dependencies
    else:
        with pytest.raises(TypeError):
            download_dependencies(dependencies)

